#!/usr/bin/env python3
"""Compute ground truth for CSX-253_Q1 from report-supported evidence."""

from __future__ import annotations

import html
import json
import re
from datetime import date
from pathlib import Path


TASK_ID = "CSX-253_Q1"
EVENT_ID = "CSX-253"
DIFFICULTY_LEVEL = "L3"
TARGET_FAMILY = "sao_sebastiao_reported_flood_landslide_mechanism"

ANCHOR_PATH = "data/event_reports/event_reports_002_Locked_event_anchor_2023_Sao_Sebastiao_compound_flood-landslide_disaster.json"
REPORT_PATH = "data/event_reports/event_reports_005_001_event_anchor_report_Locked_anchor_NASA_Earth_Observatory.html.html"


def load_json(package_dir: Path, relative_path: str) -> dict:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(package_dir: Path, relative_path: str) -> str:
    with (package_dir / relative_path).open("r", encoding="utf-8", errors="ignore") as handle:
        return handle.read()


def clean_html(fragment: str) -> str:
    fragment = re.sub(r"<script\b.*?</script>", " ", fragment, flags=re.I | re.S)
    fragment = re.sub(r"<style\b.*?</style>", " ", fragment, flags=re.I | re.S)
    fragment = re.sub(r"<[^>]+>", " ", fragment)
    return re.sub(r"\s+", " ", html.unescape(fragment)).strip()


def article_body(package_dir: Path) -> str:
    raw = read_text(package_dir, REPORT_PATH)
    paragraphs = re.findall(r"<p[^>]*>(.*?)</p>", raw, flags=re.I | re.S)
    body = []
    for paragraph in paragraphs:
        text = clean_html(paragraph)
        lower = text.lower()
        if any(term in lower for term in ["torrential", "landslide", "saturated", "680", "highway", "são sebasti"]):
            if "article dry-season floods" not in lower and "tropical cyclone" not in lower:
                body.append(text)
    return " ".join(body)


def inclusive_days(start_date: str, end_date: str) -> int:
    return (date.fromisoformat(end_date) - date.fromisoformat(start_date)).days + 1


def day_lag(start_date: str, end_date: str) -> int:
    return (date.fromisoformat(end_date) - date.fromisoformat(start_date)).days


def has(pattern: str, text: str) -> bool:
    return bool(re.search(pattern, text, flags=re.I))


def first_int(pattern: str, text: str, label: str) -> int:
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"missing {label}")
    return int(match.group(1).replace(",", ""))


RUBRIC_CRITERIA = [
    {
        "name": "Correct mechanism and response priority",
        "points": 4,
        "description": "Identifies rainfall-triggered compound flooding and landsliding, and assigns a localized steep coastal community and lifeline response priority.",
        "partial_credit": "Award partial credit for identifying heavy-rain flooding or landslides without the compound cascade, or for naming the compound mechanism but missing the localized lifeline priority.",
    },
    {
        "name": "Report-supported numeric anchors",
        "points": 4,
        "description": "Uses 680 mm in 24 hours, a 4-day event window, and a 5-day post-event image lag.",
        "partial_credit": "Award partial credit for two of the three numeric anchors or for correct values with unclear provenance.",
    },
    {
        "name": "Rainfall-saturation process signals",
        "points": 3,
        "description": "Counts the four rain-saturation signals: torrential rain, 680 mm in a day, saturated soils/hillslopes, and high seasonal rainfall plus steep slopes.",
        "partial_credit": "Award partial credit for two or three correctly identified signals.",
    },
    {
        "name": "Infrastructure and access signals",
        "points": 3,
        "description": "Counts the four terrain/impact signals: hilly or coastal municipality, homes/infrastructure impacts, destroyed buildings, and blocked highway SP-55/BR-101.",
        "partial_credit": "Award partial credit for two or three correctly identified impact/access signals.",
    },
    {
        "name": "Physical impact chain",
        "points": 3,
        "description": "Explains the causal sequence from intense localized rain to soil saturation, slope failure, flooding, and infrastructure or access impacts.",
        "partial_credit": "Award partial credit for a correct but incomplete chain.",
    },
    {
        "name": "Rejection of competing mechanisms",
        "points": 2,
        "description": "Rejects burn-scar runoff, heat stress, wind damage, and spatially uniform regional hazard as weaker explanations.",
        "partial_credit": "Award partial credit for rejecting only some alternatives.",
    },
    {
        "name": "Format and uncertainty discipline",
        "points": 1,
        "description": "Returns the requested compact JSON and avoids unsupported exact casualty claims or gridded-product precision claims.",
        "partial_credit": "Award partial credit for a mostly clear answer with minor JSON formatting issues.",
    },
]


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    anchor = load_json(package_dir, ANCHOR_PATH)
    report_text = article_body(package_dir)

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    event_window_days = inclusive_days(start_date, end_date)
    image_date = "2023-02-26"
    image_lag_after_event_end_days = day_lag(end_date, image_date)
    reported_24h_rain_mm = first_int(r"more than\s+([0-9,]+)\s+millimeters", report_text, "reported rainfall")

    rain_saturation_signals = {
        "torrential_rain": has(r"torrential rain", report_text),
        "reported_680_mm_24h": has(r"680 millimeters.*single day|single day.*680 millimeters", report_text),
        "saturated_soils_or_hillslopes": has(r"saturated soils|hillslopes saturated", report_text),
        "seasonal_rainfall_steep_slopes": has(r"high seasonal rainfall.*steep slopes", report_text),
    }
    infrastructure_access_signals = {
        "hilly_or_coastal_municipality": has(r"coastal municipality|hilly landscape", report_text),
        "homes_or_infrastructure_impacted": has(r"homes and infrastructure", report_text),
        "buildings_destroyed": has(r"destroyed several buildings", report_text),
        "highway_blocked": has(r"blocked parts highway SP-55|blocked parts.*BR-101", report_text),
    }
    rain_saturation_signal_count = sum(1 for value in rain_saturation_signals.values() if value)
    infrastructure_access_signal_count = sum(1 for value in infrastructure_access_signals.values() if value)

    answer = "rainfall_triggered_compound_flood_landslide"
    priority = "localized_steep_coastal_community_lifeline_priority"
    impact_chain = [
        "extreme_24h_rainfall",
        "soil_saturation_landslides_and_flooding",
        "prioritize_steep_settlements_buildings_highway_access",
    ]
    key_metrics = {
        "reported_24h_rain_mm": reported_24h_rain_mm,
        "event_window_days": event_window_days,
        "image_lag_after_event_end_days": image_lag_after_event_end_days,
        "rain_saturation_signal_count": rain_saturation_signal_count,
        "infrastructure_access_signal_count": infrastructure_access_signal_count,
    }

    primary_gt = {
        "answer": answer,
        "priority": priority,
        "key_metrics": key_metrics,
        "impact_chain": impact_chain,
    }

    computed_gt = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": DIFFICULTY_LEVEL,
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": "2023 Sao Sebastiao compound flood-landslide disaster",
            "event_window": {"start_date": start_date, "end_date": end_date},
            "image_date": image_date,
            "rain_saturation_signals": rain_saturation_signals,
            "infrastructure_access_signals": infrastructure_access_signals,
            "canonical_stance": (
                "The disaster is best attributed to intense localized rainfall that saturated steep coastal slopes, "
                "causing compound landslides and flooding and requiring priority attention to settled slopes, buildings, roads, and access lifelines."
            ),
            "forbidden_claims": [
                "the answer requires exact casualty counts",
                "burn-scar runoff, heat stress, or wind damage is the dominant mechanism",
                "the hazard should be treated as spatially uniform across the whole region",
                "gridded products exactly reproduce the public point rainfall total everywhere",
            ],
        },
        "numeric_tolerances": {
            "reported_24h_rain_mm": 0,
            "event_window_days": 0,
            "image_lag_after_event_end_days": 0,
            "rain_saturation_signal_count": 0,
            "infrastructure_access_signal_count": 0,
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC_CRITERIA,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                ANCHOR_PATH,
                REPORT_PATH,
            ],
            "notes": [
                "Off-event gridded precipitation, point weather, WorldPop, dNBR, and AlphaEarth products are not used in this ground truth.",
                "The official answer path uses the event anchor and NASA Earth Observatory report text.",
            ],
        },
    }

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
